// Validación de la entrada: número de incidencia de Mantis o código del manual. Nada más.
    const j = $input.first().json;
    const desdeWeb = Boolean(j.query || j.headers);
    const crudo = String((j.query && j.query.id) ?? j.issueId ?? j.id ?? '').trim().replace(/^#/, '').slice(0, 40);
    let tipo;
    if (!crudo) tipo = 'formulario';
    else if (/^\d{1,7}$/.test(crudo)) tipo = 'mantis';
    else if (/^GH-[A-Z]{2,4}-\d{3}$/i.test(crudo)) tipo = 'codigo';
    else tipo = 'invalido';
    if (!desdeWeb && tipo !== 'mantis' && tipo !== 'codigo') throw new Error('Diagnóstico: el flujo 01 no pasó un ID de incidencia válido');
    return [{ json: { id: tipo === 'codigo' ? crudo.toUpperCase() : crudo, tipo, origen: desdeWeb ? 'web' : 'flujo01' } }];

const CSS = "body{font-family:system-ui,Segoe UI,sans-serif;max-width:860px;margin:24px auto;padding:0 16px;color:#1d2330;background:#f6f7f9;line-height:1.5}h1{font-size:1.5rem}h2{font-size:1.15rem;margin-top:1.6em}.caja{background:#fff;border:1px solid #dde1e7;border-radius:10px;padding:16px 20px;margin:12px 0}.estado{font-weight:700;padding:10px 14px;border-radius:8px}.ok{background:#e3f6e8;color:#13612e}.deg{background:#fff4dc;color:#7a4b00}.mal{background:#fde4e4;color:#8a1414}.gris{background:#eceff3}code{background:#eef1f5;padding:1px 5px;border-radius:4px;font-size:.92em;word-break:break-word}table{border-collapse:collapse;width:100%}td{border-bottom:1px solid #eceff3;padding:6px 4px;vertical-align:top}input{font-size:1rem;padding:8px 10px;border:1px solid #c5cbd3;border-radius:6px;width:220px}button{font-size:1rem;padding:8px 16px;border:0;border-radius:6px;background:#2357d9;color:#fff;cursor:pointer}small{color:#5b6472}";
